Given a rod of length n and an array price[]. price[i] denotes the price of a piece of length i. Determine the maximum amount obtained by cutting the rod into pieces and selling the pieces.Note: price[0] is always 0.Input: price[] =  [0, 1, 5, 8, 9, 10, 17, 17, 20]Output: 22Explanation:  The maximum obtainable value is 22 by cutting in two pieces of lengths 2 and 6, i.e., 5 + 17 = 22.Input : price[] =  [0, 3, 5, 8, 9, 10, 17, 17, 20]Output : 24Explanation : The maximum obtainable value is 24 by cutting the rod into 8 pieces of length 1, i.e, 8*price[1]= 8*3 = 24.Input : price[] =  [0, 3]Output : 3Explanation: There is only 1 way to pick a piece of length 1.Try It YourselfTable of ContentUsing Recursion - O(2^n) Time and O(n) SpaceUsing the idea of Unbounded Knapsack - O(n^2) time and O(n^2) spaceUsing Top-Down DP (Memoization) - O(n^2) Time and O(n) SpaceUsing Bottom-Up DP (Tabulation) - O(n^2) Time and O(n) SpaceUsing Recursion - O(2^n) Time and O(n) SpaceFor a rod of length i, try all possible cuts j (1 ≤ j ≤ i).For each cut, add the price of length j with the best profit of remaining rod (i − j).Take the maximum profit among all possible cuts.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int cutRodRecur(int i, vector<int>& price) {

    // Base case
    if (i == 0) return 0;

    int ans = 0;

    // Find maximum value for rod of length i
    // by considering each cut of length j 
    // such that j <= i
    for (int j = 1; j <= i; j++) {
        ans = max(ans, price[j] + cutRodRecur(i - j, price));
    }

    return ans;
}

int cutRod(vector<int>& price) {
    int n = price.size() - 1;

    return cutRodRecur(n, price);
}

int main() {
    vector<int> price = {0, 1, 5, 8, 9, 10, 17, 17, 20};
    cout << cutRod(price);
    return 0;
}


