            C++

    #include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int cutRod(vector<int>& price) {
    int n = price.size() - 1;
    vector<int> dp(n + 1, 0);

    // Find maximum value for all 
    // rod of length i.
    for (int i = 1; i <= n; i++) {

        // dividing rod of length i 
        // into smaller piecess recursively
        for (int j = 1; j <= i; j++) {
            dp[i] = max(dp[i], price[j] + dp[i - j]);
        }
    }

    return dp[n];
}

